import { tracks, trackById } from './data.js';
export const STORAGE_KEY='prizify:v1';
export const defaultState=()=>({liked:['t1','t2','t5'],savedAlbums:['golden','soft'],followedArtists:['golden','coast'],playlists:[{id:'p-first-light',title:'First light',description:'For slow mornings and a fresh start.',art:'first',trackIds:['t1','t3','t5','t6']},{id:'p-on-the-move',title:'On the move',description:'A soundtrack for wherever the day goes.',art:'move',trackIds:['t4','t7','t10']}],recent:['t1','t2','t4','t5'],queue:['t2','t5','t3','t6','t4'],current:'t1',shuffle:false,repeat:'off',volume:.7});
export function readState(storage){try{const raw=JSON.parse(storage.getItem(STORAGE_KEY));if(!raw || !Array.isArray(raw.playlists))return defaultState();const s={...defaultState(),...raw};const artKeys=['golden','soft','sunday','midnight','coast','bloom','focus','mix','fresh','first','move'];s.playlists=s.playlists.filter(p=>p&&/^p-[\w-]+$/.test(p.id)&&typeof p.title==='string'&&Array.isArray(p.trackIds)).map(p=>({id:p.id,title:p.title.slice(0,60),description:typeof p.description==='string'?p.description.slice(0,160):'',art:artKeys.includes(p.art)?p.art:'first',originalId:typeof p.originalId==='string'&&/^[\w-]+$/.test(p.originalId)?p.originalId:undefined,trackIds:[...new Set(p.trackIds.filter(id=>trackById(id)))]}));for(const key of ['liked','recent','queue'])s[key]=Array.isArray(s[key])?s[key].filter(id=>trackById(id)):[];if(!trackById(s.current))s.current='t1';s.volume=Number.isFinite(s.volume)?Math.min(1,Math.max(0,s.volume)):.7;s.shuffle=Boolean(s.shuffle);if(!['off','all','one'].includes(s.repeat))s.repeat='off';s.savedAlbums=Array.isArray(s.savedAlbums)?s.savedAlbums.filter(id=>artKeys.includes(id)):[];s.followedArtists=Array.isArray(s.followedArtists)?s.followedArtists.filter(id=>artKeys.includes(id)):[];return s;}catch{return defaultState();}}
export function moveItem(list,from,to){if(from<0||to<0||from>=list.length||to>=list.length)return [...list];const result=[...list];result.splice(to,0,result.splice(from,1)[0]);return result;}
export const formatTime=seconds=>`${Math.floor((seconds||0)/60)}:${String(Math.floor((seconds||0)%60)).padStart(2,'0')}`;
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function searchTracks(query,category='All'){const q=query.trim().toLowerCase();return tracks.filter(t=>(!q||`${t.title} ${t.artist} ${t.album} ${t.genre} ${t.mood}`.toLowerCase().includes(q))&&(category==='All'||t.genre===category||t.mood===category));}
